import zipfile
from lxml import etree
ns = {'s': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
R_NS = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
REL_NS = {'r': 'http://schemas.openxmlformats.org/package/2006/relationships'}

path='/root/output/result_temp.xlsx'
with zipfile.ZipFile(path,'r') as z:
    wbxml=etree.fromstring(z.read('xl/workbook.xml'))
    task_rid=None
    for sh in wbxml.findall('.//s:sheet',ns):
        if sh.get('name')=='Task':
            task_rid=sh.get(f'{{{R_NS}}}id')
            print('Task rid',task_rid)
    rels=etree.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    for rel in rels.findall('.//r:Relationship',REL_NS):
        if rel.get('Id')==task_rid:
            print('Target:',rel.get('Target'))
            print('Type:',rel.get('Type'))

    # list worksheet paths
    print('Worksheet files:')
    for name in z.namelist():
        if name.startswith('xl/worksheets/') and name.endswith('.xml'):
            print(' ',name)
